import { useSetOverlayState } from './useSetOverlayState.js';
import { useTooltip } from './useTooltip.js';
import { nodePadding } from '../functions/node-padding.js';
import {
  useTooltipPinnedState,
  useTooltipVisibleState,
  useVisibleNodesState,
} from '../store/selectors.js';

export const useOverlayHandlers = () => {
  const visibleNodes = useVisibleNodesState();
  const { setTooltipContent, setTooltipPinned, setTooltipPosition } =
    useTooltip();

  const pinned = useTooltipPinnedState();
  const visible = useTooltipVisibleState();
  const { setOverlayStateInBounds } = useSetOverlayState();

  const onMouseMoveHandler = (event: React.MouseEvent<HTMLDivElement>) => {
    const { clientX, clientY, currentTarget } = event;
    const { top, left } = (currentTarget as Element).getBoundingClientRect();

    const position = {
      x: clientX,
      y: clientY,
    };

    const relativePosition = {
      x: position.x - left,
      y: position.y - top,
    };

    const tooltipData = visibleNodes.find((node) => {
      const padding = nodePadding(node);

      return (
        node.x0 - padding <= relativePosition.x &&
        node.x1 + padding >= relativePosition.x &&
        node.y0 - padding <= relativePosition.y &&
        node.y1 + padding >= relativePosition.y
      );
    });
    if (tooltipData) {
      setTooltipContent(tooltipData);
      setTooltipPosition(position);
    }
  };

  const onMouseEnterHandler = () => {
    setOverlayStateInBounds(true);
  };

  const onMouseLeaveHandler = () => {
    setOverlayStateInBounds(false);
  };

  const onClickHandler = (event: React.MouseEvent<HTMLDivElement>) => {
    event.stopPropagation();

    visible && setTooltipPinned(!pinned);
  };

  return {
    onClickHandler,
    onMouseMoveHandler,
    onMouseLeaveHandler,
    onMouseEnterHandler,
  };
};
